import logging
records = []
class H(logging.Handler):
    def emit(self, record):
        records.append(record.levelno)
lg = logging.getLogger("t_crit"); lg.setLevel(logging.DEBUG); lg.addHandler(H()); lg.propagate = False
try:
    log_check(lg, "weight_sum", "FAIL", "CRITICAL", "W02")
except RuntimeError:
    pass
else:
    raise AssertionError("no RuntimeError")
assert records == [50], records

